"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _sigmoid(x):
    return 1.0 / (1.0 + gl.exp(-x))

@gluon.jit
def _weight_offset(n, k, K: gl.constexpr):
    return n // 16 * K * 16 + k // 16 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _pop_four(k0, k1, k2, k3, maximum):
    take = k0 == maximum
    return (gl.where(take, k1, k0), gl.where(take, k2, k1), gl.where(take, k3, k2), gl.where(take, 0, k3))

@gluon.jit
def _combine_routes(Y, Weights, Out, H: gl.constexpr, RP: gl.constexpr, B: gl.constexpr):
    row = gl.program_id(0)
    k = gl.program_id(1) * B + gl.arange(0, B, layout=gl.BlockedLayout([1], [64], [1], [0]))
    acc = gl.full((B,), 0, gl.float32, gl.BlockedLayout([1], [64], [1], [0]))
    for slot in gl.static_range(RP):
        v = gl.load(Y + (row * RP + slot) * H + k, k < H, 0).to(gl.float32)
        w = gl.load(Weights + row * RP + slot)
        acc += v * w
    gl.store(Out + row * H + k, acc, k < H)

